mapper.select:
SELECT m.BATCH_SEQ AS batchSeq, m.TRADE_MARKET AS tradeMarket, t1.customerId, to_char(t1.secAcctName) as secAcctName, t2.ps AS ps, t3.termType AS termType, m.FEE_TYPE AS feeType, m.TRADE_TYPE AS tradeType, m.CHARGE_TYPE AS chargeType, m.EFF_DATE as effDate, m.CHARGE_BASIS as chargeBasis, m.FEE_MAXI as feeMaxi, m.FEE_MINI as feeMini, case when m.CHARGE_TYPE='01' then m.CHARGE_RATE * 1000 else m.CHARGE_VALUE end as chargeValue, case when m.CHARGE_TYPE='01' then m.CHARGE_RATE else m.CHARGE_VALUE end as feeRateSort, m.CHARGE_RATE as chargeRate, m.IS_PAY_WITH_TRADE as isPayWithTrade, m.PORTFOLIO_ID as portfolioId, m.ASSET_CLASSIFY1 as assetClassify1, m.ASSET_CLASSIFY2 as assetClassify2, m.BROKER_BAER_FEE as brokerBaerFee, m.COMM_CAL_METHOD as commCalMethod, m.RETENTION_BIT as retentionBit, m.OTHRER_RETENTION_BIT as othrerRetentionBit, m.IS_GRADE as isGrade, m.REMARK as remark, m.CAPITAL_ACCOUNT_NO FROM ( select BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE ,t.IS_PAY_WITH_TRADE ,t.PORTFOLIO_ID,t.ASSET_CLASSIFY1,t.ASSET_CLASSIFY2,t.BROKER_BAER_FEE,t.COMM_CAL_METHOD,t.RETENTION_BIT,t.OTHRER_RETENTION_BIT,t.IS_GRADE,t.REMARK,t.CAPITAL_ACCOUNT_NO from TRD_FEE_CONFIG t inner join TRD_FEE_CONFIG_DETAIL t1 on t.SEQ_NO=t1.CONFIG_SEQ_NO where t.FEE_TYPE IN('B01','B02','B03','B04','B05','B06','B07') GROUP BY t.BATCH_SEQ,TRADE_MARKET , FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE,CHARGE_BASIS,T1.FEE_MAXI,t1.FEE_MINI,T1.CHARGE_VALUE,t1.CHARGE_RATE,t.IS_PAY_WITH_TRADE ,t.PORTFOLIO_ID,t.ASSET_CLASSIFY1,t.ASSET_CLASSIFY2,t.BROKER_BAER_FEE,t.COMM_CAL_METHOD,t.RETENTION_BIT,t.OTHRER_RETENTION_BIT,t.IS_GRADE,t.REMARK,t.CAPITAL_ACCOUNT_NO ) m INNER JOIN ( select n.BATCH_SEQ,
regexp_replace(LISTAGG( n.customer_id, ',') WITHIN GROUP (order by (n.customer_id)) ,'([^,]+)(,\1)*(,|$)','\1\3') customerId , to_char(wm_concat(DISTINCT n1.customer_name))as secAcctName from TRD_FEE_CONFIG n left join mst_customer_info n1 on n.customer_id=n1.customer_id where n.FEE_TYPE IN('B01','B02','B03','B04','B05','B06','B07') GROUP BY n.BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t1 on m.BATCH_SEQ=t1.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
regexp_replace(LISTAGG( ps, ',') WITHIN GROUP (order by (ps)) ,'([^,]+)(,\1)*(,|$)','\1\3') ps from TRD_FEE_CONFIG where FEE_TYPE IN('B01','B02','B03','B04','B05','B06','B07') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t2 on m.BATCH_SEQ=t2.BATCH_SEQ INNER JOIN ( select BATCH_SEQ,
regexp_replace(LISTAGG( TERM_TYPE, ',') WITHIN GROUP (order by (TERM_TYPE)) ,'([^,]+)(,\1)*(,|$)','\1\3') termType from TRD_FEE_CONFIG where FEE_TYPE IN('B01','B02','B03','B04','B05','B06','B07') GROUP BY BATCH_SEQ,TRADE_MARKET ,FEE_TYPE,TRADE_TYPE,CHARGE_TYPE,EFF_DATE ) t3 on m.BATCH_SEQ=t3.BATCH_SEQ
where m.TRADE_MARKET in (#{TRADE_PLACE_03},#{TRADE_PLACE_04})
and m.FEE_TYPE=#{feeType,jdbcType=VARCHAR}
and m.TRADE_MARKET = #{tradeMarket}
and m.TRADE_TYPE in
#{item}
and m.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and m.PORTFOLIO_ID = #{portfolioId}
and t1.customerId = #{customerId}
and m.CAPITAL_ACCOUNT_NO = #{capitalAccountNo}
order by m.BATCH_SEQ,m.EFF_DATE desc

SELECT
count(1)
FROM TRD_FEE_CONFIG m
where

m.TRADE_TYPE = #{tradeType,jdbcType=VARCHAR}


	and m.ps = #{ps,jdbcType=VARCHAR}



	and m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}



	and m.EFF_DATE = to_date(#{effDate,jdbcType=VARCHAR},'yyyy-mm-dd HH24:mi:ss')



	and m.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}


	and  BATCH_SEQ <> #{batchSeq}



	and m.TERM_TYPE = #{termType,jdbcType=VARCHAR}



	and m.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}







	and m.ASSET_CLASSIFY1 = #{assetClassify1,jdbcType=VARCHAR}


	and m.ASSET_CLASSIFY2 = #{assetClassify2,jdbcType=VARCHAR}



	and m.TRADE_MARKET_MODE = #{tradeMarketMode,jdbcType=VARCHAR}



	and m.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


	and m.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


	and m.PORTFOLIO_ID is NULL
